def schema(example):
 if example is None:return {'type':'string','nullable':True}
 if isinstance(example,bool):return {'type':'boolean'}
 if isinstance(example,int):return {'type':'integer'}
 if isinstance(example,float):return {'type':'number'}
 if isinstance(example,list):return {'type':'array','items':schema(example[0]) if example else {'type':'object'}}
 if isinstance(example,dict):return {'type':'object','properties':{k:schema(v) for k,v in example.items()}}
 return {'type':'string',**({'format':'uuid'} if re.fullmatch('[a-f0-9-]{36}',example) else {})}
def add(path,method,tag,title,body=None,result=None,permission=None,description='',binary=None,public=False):
 response={'description':'Resultado confirmado','content':{'application/json':{'schema':schema(result or {}),'example':result or {}}}}
 operation={'summary':title,'tags':[tag],'description':description or title,'responses':{'200':response,**{str(status):{'description':label,'content':{'application/json':{'example':{'error':{'code':code,'message':label}}}}} for status,label,code in [(400,'Datos inválidos','INVALID_INPUT'),(401,'Autenticación requerida','UNAUTHORIZED'),(403,'Permiso u origen no autorizado','FORBIDDEN'),(404,'Recurso no visible para la organización','NOT_FOUND'),(409,'Estado, versión, evidencia o balance incompatible','CONFLICT'),(503,'Servicio u operación sin confirmar; conservar identificador original','SERVICE_UNAVAILABLE')]}},'operationId':method+'_'+re.sub('[^a-zA-Z0-9]+','_',path).strip('_')}
 if permission:operation['x-permission']=permission
 if public:operation['security']=[]
 if body is not None:operation['requestBody']={'required':True,'content':{'application/json':{'schema':{**schema(body),'required':[key for key in body if key not in ['correctionOf','correctionReason','quarantineDecision','reviewReason','location','concessionId']]},'example':body}}}
 parameters=[{'name':key,'in':'path','required':True,'schema':{'type':'string','format':'uuid'}} for key in re.findall(r'{(\w+)}',path)]
 if parameters:operation['parameters']=parameters
 if binary:operation['responses']['200']={'description':'Archivo autorizado','content':{binary:{'schema':{'type':'string','format':'binary'}}}}
 spec['paths'].setdefault(path,{})[method]=operation
